# SPDX-License-Identifier: GPL-3.0-or-later
"""Reproduce the unchanged OEM logo ROM and pixel-exact preview. No printer I/O."""
import argparse
import base64
import hashlib
import json
from pathlib import Path
import zlib

ROOT = Path(__file__).resolve().parents[1]
SHA = '0082d29a88eef7515547189dedd83a7ef8b50fc32f0ab93ef307fb58439560d5'
HEADER = '''/* Original Zortrax Inventure r0323 logo, 160x40 at (48,12).
 * Recovered from descriptor 0x0802c910, decoded SHA-256:
 * 0082d29a88eef7515547189dedd83a7ef8b50fc32f0ab93ef307fb58439560d5
 * Generated by ci/generate_startup_logo.py. OEM artwork, unchanged tones.
 * Read-only flash: no additional framebuffer or decompression buffer. */
static const uint8_t m300_startup_logo[40][80] = {
'''

def verify_or_write(check=False):
    source=ROOT/'docs/assets/startup/zortrax_logo_r0323.json'
    spec=json.loads(source.read_text())
    assert (spec['width'],spec['height'],spec['x'],spec['y'])==(160,40,48,12)
    raw=zlib.decompress(base64.b64decode(spec['zlib_b64'],validate=True))
    assert len(raw)==3200 and hashlib.sha256(raw).hexdigest()==spec['decoded_sha256']==SHA
    text=HEADER+''.join('    {'+','.join('0x%02x'%v for v in raw[y*80:(y+1)*80])+'},\n' for y in range(40))+'};\n'
    target=ROOT/'mcu/SOURCE_MCU/overlay/src/stm32/m300_oled_startup_logo.inc'
    if check:
        assert target.read_text()==text,'Generated OEM logo ROM differs from master'
    else:
        target.write_text(text)
    print(json.dumps(dict(status='PASS_OEM_STARTUP_LOGO',width=160,height=40,
        x=48,y=12,decoded_sha256=SHA,rom_bytes=3200,additional_framebuffer_bytes=0,
        native_levels=list(sorted({n for b in raw for n in (b>>4,b&15)})),
        physical_panel_tested=False)))
    return raw

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    verify_or_write(args.check)
